mapper.select:
SELECT a.REPORT_ID, a.YEAR, a.QUARTER, a.INSPECTED_GUOKU_ID, a.BOOKORG_ID, a.BOOKORG_DSCR, a.PERIOD_YEAR, a.PERIOD_NUM, a.PERIOD_AMT, a.FILLING_DATE, a.INCOME_STATE, a.PAYOUT_STATE, a.BACK_STATE, a.CORR_STATE, a.NB_STATE, a.ACCT_STATE, a.REV_ACC_STATE, a.HANG_STATE, a.REMIT_STATE, a.QUERY_STATE, a.HAND_VOU_STATE, a.CLEAR_OTHERS, a.VOU_USE_STATE, a.BIZ_HO_STATE, a.ACCT_POS_STATE, a.OTHERS, a.QUESTION_CONTENT, a.REFORM_MEMO, a.AFTER_HEAD, a.LISTER, a.ADD_USERID, a.ADD_DATE, a.MODIFY_USERID, a.MODIFY_DATE, a.ATTACHMENT_NAME, a.PAPER_ATTACHMENT, a.PRINT_ATTACHMENT, a.IS_LOCK, CONCAT('第',substring(a.QUARTER, 6),'季度') AS QUARTER_DSCR FROM `inspection`.`inspection_postsv_report` a WHERE 1=1
AND a.REPORT_ID = #{params.REPORT_ID}
AND a.QUARTER >= #{params.START_DATE}
AND a.QUARTER <= #{params.END_DATE}
AND a.INSPECTED_GUOKU_ID = #{params.INSPECTED_GUOKU_ID}
AND a.INSPECTED_GUOKU_ID = #{params.guoku_id}
ORDER BY a.YEAR DESC, a.QUARTER DESC
LIMIT ${params.page},${params.rows}

SELECT
count(0)
FROM
`inspection`.`inspection_postsv_report` a
WHERE 1=1

    AND a.REPORT_ID = #{params.REPORT_ID}


    AND a.QUARTER >= #{params.START_DATE}


    AND a.QUARTER <= #{params.END_DATE}



        AND a.INSPECTED_GUOKU_ID = #{params.INSPECTED_GUOKU_ID}




        AND a.INSPECTED_GUOKU_ID = #{params.guoku_id}
